{
  "question": "What action must a member take if an incident occurs, even if no injury is involved? How long does the general induction process last for adult members at the Tide Workshop?",
  "expected_status": "answered",
  "expected_facts": [
    {
      "chunk_id": "63c9277f98dcc8eb",
      "quote": "Submit an incident form through the member portal before leaving the site, even if nobody was injured.",
      "source": "safety.md"
    },
    {
      "chunk_id": "c4f0ce4a0755cc50",
      "quote": "General induction lasts 45 minutes and is booked through the member portal.",
      "source": "membership.md"
    }
  ],
  "candidate": {
    "status": "answered",
    "answer": "If an incident occurs—such as a near miss or equipment fault—even without injury, a member must stop work and notify the duty steward immediately. They must also submit an incident form through the member portal before leaving the site, including the time, equipment identifier, and a factual description. The general induction process for adult members at the Tide Workshop lasts 45 minutes and is booked through the member portal.",
    "evidence": [
      {
        "chunk_id": "973de2cb039dbd1c",
        "quote": "Stop work and notify the duty steward immediately after an injury, equipment fault or near miss. The steward decides whether equipment should be isolated. Submit an incident"
      },
      {
        "chunk_id": "63c9277f98dcc8eb",
        "quote": "Submit an incident form through the member portal before leaving the site, even if nobody was injured. Include the time, equipment identifier and a factual description. Do not include another member's medical information in the general incident form. This policy does not prescribe medical treatment; emergencies require on-site emergency procedures and appropriate professional help."
      },
      {
        "chunk_id": "c4f0ce4a0755cc50",
        "quote": "Every member must complete the general induction before entering a work area. General induction lasts 45 minutes and is booked through the member portal."
      }
    ]
  },
  "cited_sources": [
